#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Convert the Markdown text to HTML using regex
    std::string html = markdown;
    std::regex regex(R"(<");
    std::regex regex2(R"(>");
    html = std::replace(html, "", regex);
    html = std::regex_replace(html, regex2, ">");
    return html;
}

